const payload = $input.first().json.body;

// Check if this is a Pull Request event
if (!payload || !payload.pull_request) {
  return {
    json: {
      isValid: false,
      reason: 'Not a Pull Request event'
    }
  };
}

const action = payload.action;
const validActions = ['opened', 'synchronize', 'reopened'];

if (!validActions.includes(action)) {
  return {
    json: {
      isValid: false,
      reason: `Action '${action}' ignored. Only reviewing on: ${validActions.join(', ')}`
    }
  };
}

const pr = payload.pull_request;
const repo = payload.repository;

return {
  json: {
    isValid: true,
    action: action,
    repoFullName: repo.full_name,
    repoOwner: repo.owner.login,
    repoName: repo.name,
    prNumber: pr.number,
    prTitle: pr.title,
    prBody: pr.body || 'No description provided.',
    prAuthor: pr.user.login,
    prUrl: pr.html_url,
    diffUrl: pr.diff_url,
    commentsUrl: pr.comments_url
  }
};

const prData = $('Validate & Extract PR Info').first().json;
let rawDiff = $input.first().json.data || '';

// Limit diff length if exceptionally large to stay within token context limits
const MAX_DIFF_CHARS = 25000;
let isTruncated = false;

if (rawDiff.length > MAX_DIFF_CHARS) {
  rawDiff = rawDiff.substring(0, MAX_DIFF_CHARS) + '\n\n...[DIFF TRUNCATED DUE TO SIZE]...';
  isTruncated = true;
}

const prompt = `You are a Senior Principal Software Architect and Cybersecurity Specialist conducting an automated Pull Request code review.

### PR Context:
- **Repository:** ${prData.repoFullName}
- **PR #${prData.prNumber}:** ${prData.prTitle}
- **Author:** @${prData.prAuthor}
- **Description:** ${prData.prBody}

### Git Diff to Review:
\`\`\`diff
${rawDiff}
\`\`\`

### Instructions:
Analyze the diff thoroughly across these 3 key pillars:
1. 🐞 **Bugs & Edge Cases**: Logic errors, unhandled null/undefined, race conditions, async/await mistakes, edge case failures.
2. 🛡️ **Security & Secrets**: Hardcoded credentials, SQL/Command/XSS injection vulnerabilities, improper sanitization, risky dependencies.
3. 💎 **Code Quality & Best Practices**: Performance bottlenecks, readability, DRY violations, clean architecture, naming conventions.

### Output Format:
Produce a professional, beautifully formatted GitHub Markdown comment with:
- 🤖 **Agent Header** with a quick PR summary
- 🚦 **Verdict**: [ ✅ Approved / ⚠️ Request Changes / ❌ Critical Security Flaw ]
- 📊 **Scorecard** (Bugs: X/10, Security: Y/10, Quality: Z/10)
- 🔍 **Detailed Findings** (Grouped by file, referencing line changes with suggested code snippets in diff format where appropriate)
- 💡 **Key Recommendations / Next Steps**

Keep the tone constructive, clear, and actionable. If the PR looks completely fine, acknowledge it positively.`;

return {
  json: {
    ...prData,
    prompt: prompt,
    diffLength: rawDiff.length,
    isTruncated: isTruncated
  }
};

const prData = $('Build Agent Prompt').first().json;
const geminiResponse = $input.first().json;

let reviewText = '⚠️ AI Review could not be generated.';

try {
  if (geminiResponse.candidates && geminiResponse.candidates[0]?.content?.parts?.[0]?.text) {
    reviewText = geminiResponse.candidates[0].content.parts[0].text;
  } else if (geminiResponse.error) {
    reviewText = `❌ **AI Review Error**: ${geminiResponse.error.message || 'Unknown API Error'}`;
  }
} catch (err) {
  reviewText = `❌ **Error Parsing AI Response**: ${err.message}`;
}

const formattedComment = `## 🤖 AI Code Review Agent Report\n\n${reviewText}\n\n---\n*Reviewed automatically by [AI GitHub Code Review Agent](https://github.com/${prData.repoFullName}) powered by Google Gemini & n8n.*`;

return {
  json: {
    repoFullName: prData.repoFullName,
    prNumber: prData.prNumber,
    commentBody: formattedComment
  }
};

